SELECT gen_random_uuid()::text, 'formula', '$\alpha_s = \frac{\alpha_1R_1 + \alpha_2R_2}{R_1 + R_2}$', 'Temperature Coefficient of Series and Parallel Conductors', '$\alpha_{series} = \frac{\alpha_1R_1 + \alpha_2R_2}{R_1 + R_2},\qquad \alpha_{parallel} \approx \frac{\alpha_1R_2 + \alpha_2R_1}{R_1 + R_2}$', '$/^\circ\text{C}$', 'The combined coefficient of two materials that heat together.', '[{"symbol":"$\\alpha_1, \\alpha_2$","meaning":"coefficients of the two conductors","unit":"$/^\\circ\\text{C}$"},{"symbol":"$R_1, R_2$","meaning":"their resistances at the reference temperature","unit":"$\\Omega$"}]'::jsonb, 'Pairing a positive-α wire with a negative-α one (carbon) can make a near temperature-stable resistor. The parallel form is first-order.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Quantities/units/constants (EE)' AND t."subject" = 'EE' AND s."normKey" = 'temperature coefficients' AND s."active"), NULL, false, 'PENDING', now(), now()
