SELECT gen_random_uuid()::text, 'constant', '$1\ \text{T} = 10^4\ \text{G}$', 'Magnetic Unit Conversions', NULL, '$1\ \text{Wb} = 10^8\ \text{Mx (lines)};\ 1\ \text{T} = 10^4\ \text{G} = 64.52\ \text{kilolines/in}^2;\ 1\ \text{Oe} = \frac{1000}{4\pi} = 79.58\ \text{A/m};\ 1\ \text{Gb} = \frac{10}{4\pi} = 0.7958\ \text{A·t}$', 'Flux, flux density, field strength and mmf between SI, CGS and English units.', '[]'::jsonb, 'In CGS, B in gauss equals H in oersteds in air.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Quantities/units/constants (EE)' AND t."subject" = 'EE' AND s."normKey" = 'magnetic units (si and cgs)' AND s."active"), 'Constants', false, 'PENDING', now(), now()
