SELECT gen_random_uuid()::text, 'formula', '$\mathcal{F} = 0.4\pi NI,\ H = \frac{0.4\pi NI}{\ell}$', 'MMF and Field Strength in CGS Units', '$\mathcal{F} = 0.4\pi NI\ \text{Gb},\qquad H = \frac{0.4\pi NI}{\ell}\ \text{Oe}\ (\ell \text{ in cm}),\qquad B = \mu_rH\ \text{G}$', '$\text{Oe}$', 'Magnetic-circuit equations in gilberts and oersteds, as older texts use them.', '[{"symbol":"$N$","meaning":"turns","unit":null},{"symbol":"$I$","meaning":"current","unit":"$\\text{A}$"},{"symbol":"$\\ell$","meaning":"magnetic path length","unit":"$\\text{cm}$"},{"symbol":"$\\mu_r$","meaning":"relative permeability","unit":null}]'::jsonb, 'The 0.4π is 4π/10: it converts ampere-turns to gilberts.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Quantities/units/constants (EE)' AND t."subject" = 'EE' AND s."normKey" = 'magnetic units (si and cgs)' AND s."active"), NULL, false, 'PENDING', now(), now()
