SELECT gen_random_uuid()::text, 'formula', '$\frac{A_2}{A_1} = 2^{(n_1 - n_2)/3}$', 'AWG Size Steps', '$\frac{A_2}{A_1} = 2^{(n_1 - n_2)/3}\approx 1.26^{\,n_1 - n_2},\qquad \frac{R_2}{R_1} = \frac{A_1}{A_2}$', NULL, 'Every 3 gauges doubles the area (halves the resistance); every 10 gauges is about ten times.', '[{"symbol":"$n_1, n_2$","meaning":"AWG numbers (0 = 1/0, −1 = 2/0, …)","unit":null},{"symbol":"$A_1, A_2$","meaning":"cross-sectional areas","unit":null}]'::jsonb, 'A smaller gauge number is a thicker wire. #10 copper is about 1 Ω per 1000 ft.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Quantities/units/constants (EE)' AND t."subject" = 'EE' AND s."normKey" = 'wire gauges' AND s."active"), NULL, true, 'PENDING', now(), now()
