SELECT gen_random_uuid()::text, 'constant', '$\#14 = 2.08\ \text{mm}^2,\ \#10 = 5.26\ \text{mm}^2$', 'Common AWG and Metric Wire Sizes', NULL, '$\#14\ 2.08;\ \#12\ 3.31;\ \#10\ 5.26;\ \#8\ 8.37;\ \#6\ 13.3;\ \#4\ 21.2;\ \#2\ 33.6;\ 1/0\ 53.5;\ 4/0\ 107.2\ \text{mm}^2\ (211\,600\ \text{cmil}).\ \text{Metric: } 1.5, 2.5, 4, 6, 10, 16, 25, 35, 50, 70, 95, 120\ \text{mm}^2$', 'Areas of the common American gauges and the standard metric sizes.', '[]'::jsonb, 'The PEC uses mm² sizes; #14 AWG is close to, but smaller than, 2.5 mm².', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Quantities/units/constants (EE)' AND t."subject" = 'EE' AND s."normKey" = 'wire gauges' AND s."active"), 'Constants', false, 'PENDING', now(), now()
