SELECT gen_random_uuid()::text, 'formula', '$1\ \text{kcmil} = 0.5067\ \text{mm}^2$', 'Converting kcmil and mm²', '$A_{mm^2} = 0.5067 \times A_{kcmil},\qquad 1\ \text{mm}^2 = 1973.5\ \text{cmil},\qquad 1\ \text{cmil} = \tfrac{\pi}{4}\ \text{sq mil}$', '$\text{mm}^2$', 'Large conductors are sized in kcmil (MCM) in American practice and mm² in metric.', '[{"symbol":"$A_{kcmil}$","meaning":"area in thousands of circular mils (MCM)","unit":null},{"symbol":"$A_{mm^2}$","meaning":"area in square millimetres","unit":null}]'::jsonb, '500 kcmil ≈ 253 mm², close to the metric 240 mm².', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Quantities/units/constants (EE)' AND t."subject" = 'EE' AND s."normKey" = 'wire gauges' AND s."active"), NULL, false, 'PENDING', now(), now()
