SELECT gen_random_uuid()::text, 'formula', '$I = \frac{746\,\text{hp}}{\sqrt3V\eta\,\text{pf}}$', 'Motor Current from Horsepower', '$P_{in} = \frac{746\,\text{hp}}{\eta},\qquad I_{3\phi} = \frac{746\,\text{hp}}{\sqrt3\,V_L\,\eta\,\text{pf}},\qquad I_{1\phi} = \frac{746\,\text{hp}}{V\eta\,\text{pf}}$', '$\text{A}$', 'A motor''s line current from its nameplate output, efficiency and power factor.', '[{"symbol":"$\\text{hp}$","meaning":"rated output in horsepower","unit":null},{"symbol":"$V_L$","meaning":"line voltage","unit":"$\\text{V}$"},{"symbol":"$\\eta$","meaning":"efficiency","unit":null},{"symbol":"$\\text{pf}$","meaning":"power factor","unit":null}]'::jsonb, 'Horsepower is OUTPUT: divide by efficiency for input. Code sizing uses the PEC table currents, not this.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Quantities/units/constants (EE)' AND t."subject" = 'EE' AND s."normKey" = 'power and energy conversions' AND s."active"), NULL, false, 'PENDING', now(), now()
